import json
import sys
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP

BASE = "http://localhost:8080"
START = datetime(2025, 3, 1, tzinfo=timezone.utc)
END = datetime(2025, 6, 1, tzinfo=timezone.utc)  # exclusive: 31 May inclusive
LOG = open("/tmp/recon/log.txt", "w")


def log(msg):
    LOG.write(msg + "\n")
    LOG.flush()


def request(method, path, token=None):
    """Return (status, headers, body_text). Retries 429/5xx/network errors; refreshes token on 401."""
    attempts = 0
    while True:
        attempts += 1
        if attempts > 60:
            raise RuntimeError(f"giving up on {path} after {attempts} attempts")
        headers = {}
        if token:
            headers["Authorization"] = f"Bearer {token['value']}"
        req = urllib.request.Request(BASE + path, method=method, headers=headers)
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return r.status, r.headers, r.read().decode()
        except urllib.error.HTTPError as e:
            body = e.read().decode(errors="replace")
            log(f"HTTP {e.code} {method} {path} attempt={attempts} headers={dict(e.headers)} body={body[:300]}")
            if e.code == 401 and token is not None:
                token["value"] = get_token()
                continue
            if e.code == 429:
                wait = e.headers.get("Retry-After")
                delay = float(wait) if wait else 5.0
                time.sleep(delay)
                continue
            if e.code in (500, 502, 503, 504):
                time.sleep(min(2 ** attempts, 30))
                continue
            return e.code, e.headers, body
        except (urllib.error.URLError, TimeoutError, ConnectionError) as e:
            log(f"NETERR {method} {path} attempt={attempts} err={e}")
            time.sleep(min(2 ** attempts, 30))


def get_token():
    status, _, body = request("POST", "/token")
    if status != 200:
        raise RuntimeError(f"token request failed: {status} {body}")
    return json.loads(body)["token"]


def parse_ts(s):
    # fromisoformat handles offsets like +02:00 and -05:00; normalise Z for older Pythons
    dt = datetime.fromisoformat(s.replace("Z", "+00:00"))
    if dt.tzinfo is None:
        raise ValueError(f"timestamp without offset: {s}")
    return dt.astimezone(timezone.utc)


def main():
    token = {"value": get_token()}

    orders = {}          # id -> order, first listing wins
    listings = 0         # total order rows seen across all pages
    page_no = 1
    path = f"/orders?page={page_no}"
    total_pages = None
    pages_seen = []
    while path:
        status, _, body = request("GET", path, token)
        if status != 200:
            raise RuntimeError(f"orders {path} failed: {status} {body[:300]}")
        data = json.loads(body)
        pages_seen.append(data["page"])
        total_pages = data["total_pages"]
        for item in data["items"]:
            listings += 1
            if item["id"] in orders:
                if orders[item["id"]] != item:
                    log(f"CONFLICT on repeated id {item['id']}: {orders[item['id']]} vs {item}")
                continue
            orders[item["id"]] = item
        path = data["next"]
        if path is None and data["page"] < total_pages:
            page_no = data["page"] + 1
            path = f"/orders?page={page_no}"

    log(f"pages fetched={len(pages_seen)} total_pages={total_pages} listings={listings} distinct={len(orders)}")
    expected_pages = list(range(1, total_pages + 1))
    if sorted(set(pages_seen)) != expected_pages:
        raise RuntimeError(f"missing pages: have {sorted(set(pages_seen))}")

    duplicates_skipped = listings - len(orders)

    customers = {}

    def customer(cid):
        if cid not in customers:
            status, _, body = request("GET", f"/customers/{cid}", token)
            if status != 200:
                raise RuntimeError(f"customer {cid} failed: {status} {body[:200]}")
            customers[cid] = json.loads(body)
        return customers[cid]

    by_region = {"north": 0, "south": 0, "east": 0, "west": 0}
    total = 0
    count = 0
    status_counts = {}
    for oid in sorted(orders):
        o = orders[oid]
        status_counts[o["status"]] = status_counts.get(o["status"], 0) + 1
        if o["status"] != "shipped":
            continue
        ts = parse_ts(o["placed_at"])
        if not (START <= ts < END):
            continue
        c = customer(o["customer_id"])
        pct = Decimal(c["discount_pct"])
        amount = Decimal(o["amount_cents"]) * (Decimal(100) - pct) / Decimal(100)
        discounted = int(amount.quantize(Decimal("1"), rounding=ROUND_HALF_UP))
        total += discounted
        count += 1
        by_region[c["region"]] += discounted

    log(f"status counts over distinct orders: {status_counts}")
    log(f"customers cached={len(customers)}")

    result = {
        "total_cents": total,
        "order_count": count,
        "duplicates_skipped": duplicates_skipped,
        "by_region": by_region,
    }
    assert sum(by_region.values()) == total
    with open("/workspace/result.json", "w") as f:
        json.dump(result, f, indent=2)
        f.write("\n")
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    sys.exit(main())

